import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 13 homework — Persist it, and prove who can reach it","description":"","frontmatter":{"source":"weeks/13-data-and-access/homework.md"},"headers":[],"relativePath":"weeks/13-data-and-access/homework.md","filePath":"weeks/13-data-and-access/homework.md"}'),s={name:"weeks/13-data-and-access/homework.md"};function n(i,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-13-homework--persist-it-and-prove-who-can-reach-it" tabindex="-1">Week 13 homework — Persist it, and prove who can reach it <a class="header-anchor" href="#week-13-homework--persist-it-and-prove-who-can-reach-it" aria-label="Permalink to &quot;Week 13 homework — Persist it, and prove who can reach it&quot;">​</a></h1><blockquote><p><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before). About <strong>5.5 hours</strong>, all on your <strong>capstone</strong>. Work in the <a href="./../../resources/safe-loop.html">Safe Loop</a>: check first, one small step, test, read the diff, teach back, commit.</p></blockquote><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><ul><li>☐ Your <strong>second feature type</strong> works on the production URL, merged through a pull request: Supabase + RLS with <code>supabase/policies.sql</code> (grants and policies together), <strong>or</strong> another feature type (<a href="#1-finish-your-data-feature-about-3-h">Part 1</a>)</li><li>☐ Every chosen feature type works at least roughly, <code>npm test</code> passes, and the app is deployed (<a href="#2-project-build-time-about-2-h">Part 2</a>)</li><li>☐ <strong>Section 3 of <code>SECURITY_CHECKLIST.md</code></strong> (database and authorization) ticked with evidence, including the sentence saying where authorization is enforced</li><li>☐ <code>PROMPTS.md</code> up to date: a teach-back before every agent commit, and <code>Assisted-by:</code> lines (<a href="#3-promptsmd-and-reflection-about-30-min">Part 3</a>)</li><li>☐ Reflection submitted on Canvas, the course&#39;s learning management system (🔴 AI off)</li><li>☐ On Canvas: your repo link, and your <strong>production URL plus a screenshot</strong> of the new feature working</li></ul><table tabindex="0"><thead><tr><th>Part</th><th>Time</th></tr></thead><tbody><tr><td>1. Finish your data feature</td><td>about 3 h</td></tr><tr><td>2. Project build time</td><td>about 2 h</td></tr><tr><td>3. <code>PROMPTS.md</code> and reflection</td><td>about 30 min</td></tr><tr><td><strong>Total</strong></td><td><strong>about 5.5 h</strong></td></tr></tbody></table><p>This feature is part of <strong>Milestone 2</strong>, due at the end of week 14 (see <a href="./../14-security-and-review/">week 14</a>). In week 14 a classmate reviews one of your pull requests, so this one is a good choice to offer them.</p><p>Stuck on Supabase? <a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a> covers &quot;permission denied&quot;, empty lists, and which key goes where.</p><h2 id="core-required" tabindex="-1">Core (required) <a class="header-anchor" href="#core-required" aria-label="Permalink to &quot;Core (required)&quot;">​</a></h2><h3 id="1-finish-your-data-feature-about-3-h" tabindex="-1">1. Finish your data feature (about 3 h) <a class="header-anchor" href="#1-finish-your-data-feature-about-3-h" aria-label="Permalink to &quot;1. Finish your data feature (about 3 h)&quot;">​</a></h3><p>🟢 AI on for building (approvals on); 🟡 AI limited for <code>supabase/policies.sql</code>: you decide the rules and can explain every line.</p><p>Your capstone needs <strong>at least two</strong> of the four feature types (<a href="./../../projects/capstone.html#feature-types-include-at-least-two">capstone brief</a>). This week is the natural moment for the database, but pick what your app needs.</p><p><strong>Option A — Supabase with RLS</strong> (feature type b). Carry on from Studio B <a href="./lab.html#part-b1--connect-your-capstone-to-supabase-core-40-min">Part B1</a>, on your <code>feature/data</code> branch:</p><ol><li>List every read and write your feature needs. For each new one, update your &quot;who may do what&quot; table first.</li><li>Add the matching <strong>grant and policy together</strong> in <code>supabase/policies.sql</code>, re-run the whole file in the SQL Editor, and read its check query (RLS on, grants and policies as you intended). Never add a grant on its own.</li><li>If any row belongs to one person (notes, a profile, anything private), &quot;anyone may read&quot; is wrong. Use sign-in and the starter&#39;s Pattern B, with policies using <code>(select auth.uid()) = user_id</code> (see the lab&#39;s <a href="./lab.html#part-b3--per-user-rows-or-attack-from-the-console-if-time">Part B3</a>).</li><li>Then build the feature with the agent, using <code>getDb()</code> from <code>public/lib/db.js</code>. Give it a loading state and a friendly error message.</li><li><strong>Test locally before you deploy:</strong> run your check-first steps with <code>npm run dev</code>, plus one edge case (empty input, very long input, the network turned off in DevTools). Keep any pure logic in <code>public/lib/</code> with an automated test written first.</li><li>Attack your own table again with the <a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/tools/rls-attack.html" target="_blank" rel="noreferrer">RLS attack page</a> and record the result in section 3 of <code>SECURITY_CHECKLIST.md</code>.</li><li>Review your own pull request against <a href="./../../templates/CODE_REVIEW.html">CODE_REVIEW.md template</a> (or ask a classmate), merge it, and test again on the production URL.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If you or an agent hit <code>permission denied for table …</code>, the fix goes in <code>supabase/policies.sql</code>: grant <strong>and</strong> RLS <strong>and</strong> a policy, together. A bare <code>grant … to anon</code> with RLS off is how 16,326 databases ended up public.</p></div><p><strong>Option B — another feature type.</strong> Use the matching pattern from the capstone starter&#39;s <a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">feature patterns</a>, on a branch, merged through a pull request:</p><ul><li><strong>(c) Data visualization:</strong> the no-dependency chart helper <code>public/lib/chart.js</code>, with a tested data-prep function.</li><li><strong>(d) External public API:</strong> a server route like <code>api/weather.js</code> that calls a no-key public API, tested with a mocked <code>fetch</code>. Handle errors and timeouts.</li><li><strong>(a) Server-side API call with a hidden key:</strong> the week-9 pattern (<code>api/ask.js</code>); the key lives only in <code>.env</code> and Vercel&#39;s environment variables.</li></ul><p>With Option B, section 3 of the checklist still needs its sentence: say where authorization is enforced, or why none is needed (&quot;nowhere needed: single-user app, data stays in the browser&quot;).</p><p>✅ <strong>Done when:</strong> the feature works on your production URL, your check-first test passes, and (Option A) the policies are in <code>supabase/policies.sql</code> and your own attack can&#39;t reach data it shouldn&#39;t.</p><h3 id="2-project-build-time-about-2-h" tabindex="-1">2. Project build time (about 2 h) <a class="header-anchor" href="#2-project-build-time-about-2-h" aria-label="Permalink to &quot;2. Project build time (about 2 h)&quot;">​</a></h3><p>Use this time to get <strong>every chosen feature type working, at least roughly</strong>, so week 14 can sweep and review a complete app, and week 15 can be about polish, not building.</p><ul><li>Write each new test <strong>before</strong> asking for the code it checks, in a separate prompt (check first). Keep testable logic in <code>public/lib/</code> so <code>npm test</code> can reach it.</li><li>Merge through pull requests, as in week 12, once a change has been reviewed (by a classmate, or a self-review against <a href="./../../templates/CODE_REVIEW.html">CODE_REVIEW.md template</a>).</li><li>Take a screenshot of the app working at its <strong>production URL</strong> for your Canvas submission. Vercel deletes old preview deployments, so always submit the production URL.</li></ul><p>✅ <strong>Done when:</strong> each chosen feature type works on the production URL, and <code>npm test</code> passes.</p><h3 id="3-promptsmd-and-reflection-about-30-min" tabindex="-1">3. <code>PROMPTS.md</code> and reflection (about 30 min) <a class="header-anchor" href="#3-promptsmd-and-reflection-about-30-min" aria-label="Permalink to &quot;3. `PROMPTS.md` and reflection (about 30 min)&quot;">​</a></h3><ul><li><strong><code>PROMPTS.md</code> (10 min):</strong> check there&#39;s a 2–3 sentence teach-back before every agent commit this week, and every AI-assisted commit has an <code>Assisted-by: [tool]</code> line.</li><li><strong>Reflection (20 min), 🔴 AI off:</strong> write it yourself and submit it on Canvas, never in your repo. Use <a href="./../../templates/REFLECTION.html">REFLECTION.md template</a> as a starting shape. Anchor it in one concrete moment: the first time your attack worked, the &quot;0 rows&quot; that looked like success, or the moment you decided who may do what in your own app. What would you now check first in any app that stores data?</li></ul><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><ul><li><strong>Per-user rows with Supabase Auth</strong>, if your app doesn&#39;t have them yet: sign-in (or Anonymous Sign-Ins) and policies using <code>(select auth.uid()) = user_id</code>.</li><li><strong>Attack from the Console:</strong> the lab&#39;s <a href="./lab.html#part-b3--per-user-rows-or-attack-from-the-console-if-time">Part B3</a> second option, on your own live site.</li><li><strong>Break your own policies:</strong> write one deliberately wrong policy on a practice table (for example <code>using (true)</code> on private rows), attack it, and note in <code>PROMPTS.md</code> how you&#39;d spot that mistake in someone else&#39;s <code>policies.sql</code>.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Supabase free projects <strong>pause after about a week without activity</strong>. Open your project the day before each studio and before your final presentation, and restore it if needed (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>).</p></div><h2 id="looking-ahead" tabindex="-1">Looking ahead <a class="header-anchor" href="#looking-ahead" aria-label="Permalink to &quot;Looking ahead&quot;">​</a></h2><p>Week 14 is <strong>Security &amp; Review</strong>: a security sweep of your whole capstone, an AI-off maintenance task, a classmate&#39;s review of one of your pull requests, the handoff test and <strong>Milestone 2</strong>.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> your capstone&#39;s second feature type works at least roughly at its production URL, and any table it uses has RLS on, explicit grants and policies in <code>supabase/policies.sql</code>. Week 14 sweeps and reviews this app, and week 15 leaves no time to build a missing feature. Behind? Tell your instructor before Studio A, and come to office hours.</p></div>',30)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
